// LongLove dashboard bundle — 2026-10-27
const uid=()=>crypto.randomUUID();
const pick=a=>a[Math.floor(Math.random()*a.length)];
const day=(t=Date.now())=>new Date(t+8*3600000).toISOString().slice(0,10);
const originalCards=['怎么这么晚还在看手机？','还不睡？要我陪你吗？','又在偷偷刷视频？','想我了没？','过来，让我抱抱。'];
const dailyCards=['刚才路过一家花店，忽然想起你。','今天过得怎么样？慢慢说，我听着。','忙完了，来陪你待一会儿。','记得喝水，也给自己一点休息的时间。','想和你分享今天的小事。','窗外的风很好，想和你一起走走。','没有什么特别的事，就是想找你说说话。'];
function initial(){return {version:1,profile:{name:'我',avatar:'',signature:''},roles:[{id:'first',name:'TA',avatar:'',signature:'',color:'#b6c5ad',wallet:1000}],selected:'first',cards:[{id:'huit',name:'HUIT · 原始字卡',enabled:true,items:originalCards},{id:'daily',name:'日常陪伴',enabled:true,items:dailyCards}],chats:{first:[]},moments:[],letters:[],events:[],ledger:[],products:[{id:'p1',name:'一束白色郁金香',price:88,emoji:'🌷',description:'把想念放进花里',image:''},{id:'p2',name:'双人电影票',price:120,emoji:'🎞️',description:'下次，一起坐最后一排',image:''},{id:'p3',name:'手写明信片',price:25,emoji:'✉️',description:'寄一封慢慢抵达的信',image:''},{id:'p4',name:'热可可',price:18,emoji:'☕',description:'今天也要暖暖的',image:''}],wallet:1000,inventory:[],tarot:[],calls:[],trace:{},hands:[],stickers:[],settings:{replyMin:1,replyMax:120,stickerChance:20,active:true,interval:60,activeChance:35,backgroundPaused:false,quietStart:23,quietEnd:8,stitchMin:1,stitchMax:4,freeChance:15,autoMoments:true,autoGifts:true,autoLetters:true,autoCalls:false},nextActiveAt:null,lastActive:Date.now(),lastAllowance:'',dictionary:{n:['晚风','月亮','花园','心事','星光'],v:['想念','遇见','拥抱','等待','喜欢'],a:['温柔','明亮','安静','漫长','柔软'],d:['轻轻地','慢慢地','悄悄地']}};}
function freeSentence(s,lexicon){const d=lexicon||s.dictionary;const get=k=>pick([...(d[k]||[]),...(s.dictionary[k]||[])])||'想念';return pick([()=>`${get('n')}，${get('a')}的${get('n')}。`,()=>`我${get('d')}${get('v')}，也${get('v')}着${get('n')}。`,()=>`如果${get('n')}能够${get('v')}，你会想到什么？`,()=>`今天的${get('n')}很${get('a')}，我想把它送给你。`,()=>`${get('a')}的${get('n')}，正在${get('d')}${get('v')}。`])();}
function reply(s,lexicon){if(Math.random()*100<s.settings.freeChance)return freeSentence(s,lexicon);const pool=s.cards.filter(g=>g.enabled).flatMap(g=>g.items);if(!pool.length)return freeSentence(s,lexicon);return Array.from({length:stitchCount(s)},()=>pick(pool)).join('，');}
function message(s,role,text,from='dream',extra={}){const m={id:uid(),time:Date.now(),from,text,...extra};(s.chats[role]??=[]).push(m);return m;}
const major=['愚者','魔术师','女祭司','皇后','皇帝','教皇','恋人','战车','力量','隐者','命运之轮','正义','倒吊人','死神','节制','恶魔','高塔','星星','月亮','太阳','审判','世界'];
const themes=['新的开始','主动表达','倾听直觉','温柔照顾','建立边界','共同信念','关系与选择','向前行动','耐心与勇气','给自己空间','接纳变化','坦诚与平衡','换个角度','告别与更新','相互协调','看见依赖','重建期待','希望与信任','面对不确定','分享快乐','重新理解','完整与相聚'];
const tarotDeck=[...major.map((name,i)=>({name,theme:themes[i]})),...['权杖','圣杯','宝剑','星币'].flatMap((s,i)=>['王牌','二','三','四','五','六','七','八','九','十','侍从','骑士','王后','国王'].map(n=>({name:s+n,theme:['行动与热情','情感与连接','思考与沟通','日常与付出'][i]})))];
function number(n,min,max){n=Number(n);if(!Number.isFinite(n)||n<min||n>max)throw Error('数值超出范围');return n;}
const clean=(v,max=5000)=>String(v??'').trim().slice(0,max);
function action(s,type,p={},lexicon){const r=s.roles.find(r=>r.id===(p.role||s.selected));switch(type){
case 'pauseBackground':s.settings.backgroundPaused=true;break;
case 'resumeBackground':s.settings.backgroundPaused=false;s.nextActiveAt=Date.now()+activeDelay(s);break;
case 'select':if(r)s.selected=r.id;break;
case 'choice':{if(!r)throw Error('梦角不存在');const question=clean(p.question,300),options=Array.isArray(p.options)?p.options.map(x=>clean(x,200)).filter(Boolean):[];if(!question)throw Error('请输入问题');if(options.length<2||options.length>10)throw Error('请填写 2–10 个选项');if(new Set(options).size!==options.length)throw Error('选项不能重复');message(s,r.id,'[抉择] '+question,'user',{type:'choice',question,options,answer:null,dueAt:Date.now()+3000+Math.floor(Math.random()*12001)});break;}
case 'choiceAnswer':if(r)resolveChoice(s,r.id,p.id);break;
case 'message':if(!r||!clean(p.text))throw Error('请填写消息');message(s,r.id,clean(p.text),p.from==='dream'?'dream':p.from==='system'?'system':'user',p.expectReply?{replyDueAt:Date.now()+replyDelay(s),replyDone:false}:{});break;
case 'reply':if(r)message(s,r.id,p.free?freeSentence(s,lexicon):reply(s,lexicon));break;
case 'deleteMessages':{if(!r)throw Error('梦角不存在');if(p.all===true)s.chats[r.id]=[];else{if(!Array.isArray(p.ids)||!p.ids.length)throw Error('请选择消息');const ids=new Set(p.ids);s.chats[r.id]=(s.chats[r.id]||[]).filter(m=>!ids.has(m.id));}break;}
case 'addSticker':{if(!/^data:image\/(png|jpeg|webp|gif);base64,[A-Za-z0-9+/=]+$/.test(p.image||'')||p.image.length>1500000)throw Error('表情图片无效或超过 1MB');s.stickers??=[];if(s.stickers.length>=100)throw Error('最多保存 100 张表情');s.stickers.push({id:uid(),name:clean(p.name,50)||'表情',image:p.image});break;}
case 'deleteSticker':s.stickers=(s.stickers||[]).filter(x=>x.id!==p.id);break;
case 'sendSticker':{const item=s.stickers?.find(x=>x.id===p.id);if(!item||!r)throw Error('表情或梦角不存在');message(s,r.id,'[表情] '+item.name,'user',{type:'sticker',image:item.image,stickerName:item.name,replyDueAt:Date.now()+replyDelay(s),replyDone:false});break;}
case 'answerMessage':if(r)resolveReply(s,r.id,p.id,Date.now(),lexicon);break;
case 'profile':s.profile={...s.profile,name:clean(p.name,40)||'我',signature:clean(p.signature,200),avatar:clean(p.avatar,1500000)};break;
case 'role':{const data={name:clean(p.name,40)||'TA',signature:clean(p.signature,200),avatar:clean(p.avatar,1500000)};if(p.id){const x=s.roles.find(x=>x.id===p.id);if(!x)throw Error('角色不存在');Object.assign(x,data);}else{s.roles.push({...data,id:uid(),wallet:1000,color:'#b6c5ad'});}break;}
case 'settings':{const lo=number(p.replyMin??s.settings.replyMin??1,1,3600),hi=number(p.replyMax??s.settings.replyMax??120,1,3600);if(lo>hi)throw Error('最短回复时间不能超过最长时间');const a=number(p.stitchMin??s.settings.stitchMin??1,1,7),b=number(p.stitchMax??s.settings.stitchMax??4,1,7);if(!Number.isInteger(a)||!Number.isInteger(b)||a>b)throw Error('字卡数量须为整数，且最少不能超过最多');s.settings.stitchMin=a;s.settings.stitchMax=b;s.settings.replyMin=lo;s.settings.replyMax=hi;}if('stickerChance' in p)s.settings.stickerChance=number(p.stickerChance,0,100);for(const k of ['active','autoMoments','autoGifts','autoLetters','autoCalls'])if(k in p)s.settings[k]=!!p[k];for(const [k,min,max] of [['interval',10,1440],['activeChance',0,100],['freeChance',0,100],['quietStart',0,23],['quietEnd',0,23]])if(k in p)s.settings[k]=number(p[k],min,max);break;
case 'cards':{const groups=p.groups;if(!Array.isArray(groups))throw Error('字卡格式错误');for(const g of groups){if(!Array.isArray(g.items))continue;const name=clean(g.name,60)||'导入字卡';let old=s.cards.find(x=>x.name===name);if(!old){old={id:uid(),name,enabled:true,items:[]};s.cards.push(old);}old.items=[...new Set([...old.items,...g.items.filter(x=>typeof x==='string').map(x=>clean(x)).filter(Boolean)])];}break;}
case 'toggleCard':{const g=s.cards.find(x=>x.id===p.id);if(g)g.enabled=!g.enabled;break;}
case 'deleteCardGroup':s.cards=s.cards.filter(x=>x.id!==p.id);break;
case 'dictionary':for(const k of ['n','v','a','d'])if(Array.isArray(p[k]))s.dictionary[k]=[...new Set([...s.dictionary[k],...p[k].filter(x=>typeof x==='string').map(x=>clean(x,30)).filter(Boolean)])];break;
case 'moment':if(!clean(p.text))throw Error('请填写动态');s.moments.unshift({id:uid(),role:p.asRole?r?.id:null,text:clean(p.text),image:clean(p.image,1500000),time:Date.now(),liked:false,comments:[]});break;
case 'like':{const x=s.moments.find(x=>x.id===p.id);if(x)x.liked=!x.liked;break;}
case 'comment':{const x=s.moments.find(x=>x.id===p.id);if(x&&clean(p.text))x.comments.push({name:s.profile.name,text:clean(p.text,500)});break;}
case 'letter':if(!r||!clean(p.text))throw Error('请填写信件');s.letters.unshift({id:uid(),role:r.id,from:'user',title:clean(p.title,80)||'写给你的信',text:clean(p.text),time:Date.now()});break;
case 'receiveLetter':if(r)s.letters.unshift({id:uid(),role:r.id,from:'dream',title:'一些想对你说的话',text:Array.from({length:3},()=>reply(s,lexicon)).join('\n\n'),time:Date.now()});break;
case 'event':if(!/^\d{4}-\d{2}-\d{2}$/.test(p.date)||!clean(p.title))throw Error('请填写日期和名称');s.events.push({id:uid(),title:clean(p.title,100),date:p.date,type:['anniversary','period','note'].includes(p.type)?p.type:'note',annual:!!p.annual,cycle:number(p.cycle||28,15,90),duration:number(p.duration||5,1,15)});break;
case 'deleteEvent':s.events=s.events.filter(x=>x.id!==p.id);break;
case 'ledger':s.ledger.unshift({id:uid(),amount:Math.round(number(p.amount,0.01,10000000)*100),type:p.type==='income'?'income':'expense',category:clean(p.category,40)||'日常',note:clean(p.note,200),date:p.date||day()});break;
case 'deleteLedger':s.ledger=s.ledger.filter(x=>x.id!==p.id);break;
case 'product':if(!clean(p.name))throw Error('请填写商品名称');s.products.push({id:uid(),name:clean(p.name,80),description:clean(p.description,200),price:Math.round(number(p.price,1,1000000)),emoji:clean(p.emoji,8)||'🎁',image:clean(p.image,1500000)});break;
case 'deleteProduct':s.products=s.products.filter(x=>x.id!==p.id);break;
case 'buy':{const item=s.products.find(x=>x.id===p.id);if(!item||!r)throw Error('商品或角色不存在');const byRole=p.buyer==='role';if((byRole?r.wallet:s.wallet)<item.price)throw Error('心意币不足');if(byRole)r.wallet-=item.price;else s.wallet-=item.price;s.inventory.unshift({id:uid(),product:{...item},buyer:byRole?r.id:'user',owner:p.gift?(byRole?'user':r.id):(byRole?r.id:'user'),time:Date.now()});message(s,r.id,p.gift?`送给${byRole?s.profile.name:r.name}：${item.name} 🎁`:`购买了 ${item.name}`,byRole?'dream':'user');break;}
case 'allowance':if(s.lastAllowance===day())throw Error('今天已领取');s.lastAllowance=day();s.wallet+=100;for(const r of s.roles)r.wallet+=100;break;
case 'tarot':{const deck=[...tarotDeck],cards=[];for(let i=0;i<(p.count===1?1:3);i++){const c=deck.splice(Math.floor(Math.random()*deck.length),1)[0];cards.push({...c,reversed:Math.random()<.5});}s.tarot.unshift({id:uid(),question:clean(p.question,300),role:r?.id,time:Date.now(),cards,message:reply(s,lexicon)});break;}
case 'call':if(r)s.calls.unshift({id:uid(),role:r.id,time:Date.now(),seconds:Math.max(0,Math.round(Number(p.seconds)||0)),missed:!!p.missed});break;
case 'hand':if(r){const text=pick(['把手轻轻放在你的掌心。','拉住了你的手，晃了晃。','用指尖碰了碰你。','给了你一个暖暖的拥抱。','牵着你，陪你安静待一会儿。']);s.hands.unshift({id:uid(),role:r.id,time:Date.now(),text});message(s,r.id,text);}break;
case 'trace':if(r){s.trace[r.id]??={};for(const [key,value] of Object.entries(p.values||{[p.key]:p.value})){if(['__proto__','constructor','prototype'].includes(key))continue;s.trace[r.id][clean(key,100)]=clean(value,1000000);}}break;
case 'import':{if(!p.data||p.data.version!==1||!Array.isArray(p.data.roles)||!Array.isArray(p.data.cards)||!p.data.chats||!p.data.settings)throw Error('不是有效的 LongLove 备份');const base=initial();for(const k of Object.keys(base))if(k in p.data)base[k]=p.data[k];if(!base.roles.length||base.roles.some(x=>!x.id||typeof x.name!=='string')||base.cards.some(x=>!Array.isArray(x.items)))throw Error('备份数据损坏');Object.assign(s,base);break;}
default:throw Error('未知操作');}return s;}
function activeDelay(s){return Math.round(Math.max(10,Number(s.settings.interval)||60)*60000*(1+Math.random()*2));}
function tick(s,now=Date.now(),lexicon){const events=[...settleChoices(s,now),...settleReplies(s,now,lexicon)];if(!s.settings.active)return events;if(!Number.isFinite(s.nextActiveAt)){s.nextActiveAt=now+activeDelay(s);return events;}if(now<s.nextActiveAt)return events;s.nextActiveAt=now+activeDelay(s);const hour=Number(new Intl.DateTimeFormat('en-GB',{hour:'2-digit',hourCycle:'h23',timeZone:'Asia/Kuala_Lumpur'}).format(now));const a=s.settings.quietStart,b=s.settings.quietEnd;if(a!==b&&(a<b?hour>=a&&hour<b:hour>=a||hour<b))return events;if(Math.random()*100>=(s.settings.activeChance??35))return events;s.lastActive=now;const r=pick(s.roles);if(!r)return events;const rand=Math.random();if(s.settings.autoGifts&&rand<.12&&s.products.some(x=>x.price<=r.wallet)){const item=pick(s.products.filter(x=>x.price<=r.wallet));action(s,'buy',{id:item.id,role:r.id,buyer:'role',gift:Math.random()<.7},lexicon);events.push({title:r.name,body:`挑选了一份 ${item.name}`,page:'shop',role:r.id});}else if(s.settings.autoMoments&&rand<.28){const text=reply(s,lexicon);action(s,'moment',{text,asRole:true,role:r.id});events.push({title:r.name+' 更新了朋友圈',body:text,page:'moments',role:r.id});}else if(s.settings.autoLetters&&rand<.36){action(s,'receiveLetter',{role:r.id},lexicon);events.push({title:r.name+' 寄来了一封信',body:'一些想对你说的话，放进信箱了。',page:'mail',role:r.id});}else if(s.settings.autoCalls&&rand<.42){action(s,'call',{role:r.id,seconds:0,missed:true});events.push({title:r.name+' 想和你通话',body:'打开 LongLove 回拨字卡通话',page:'calls',role:r.id});}else {const m=message(s,r.id,reply(s,lexicon));events.push({title:r.name,body:m.text,messageId:m.id,page:'chat',role:r.id});}return events;}

function resolveChoice(s,roleId,id,now=Date.now()){const r=s.roles.find(x=>x.id===roleId),m=s.chats[roleId]?.find(x=>x.id===id&&x.type==='choice');if(!r||!m||m.answer!==null||!Array.isArray(m.options)||m.options.length<2||Number(m.dueAt)>now)return null;m.answer=pick(m.options);m.answererName=r.name;m.answeredAt=now;const response=message(s,roleId,m.answer,'dream',{choiceId:m.id});return {title:r.name,body:'选择了「'+m.answer+'」',messageId:response.id,page:'chat',role:roleId};}
function settleChoices(s,now=Date.now()){const events=[];for(const r of s.roles){for(const m of [...(s.chats[r.id]||[])]){if(m.type==='choice'&&m.answer===null){const event=resolveChoice(s,r.id,m.id,now);if(event)events.push(event);}}}return events;}

function replyDelay(s){const min=Number(s.settings.replyMin??1),max=Number(s.settings.replyMax??120);return Math.round((min+Math.random()*(max-min))*1000);}
function resolveReply(s,roleId,id,now=Date.now(),lexicon){const r=s.roles.find(x=>x.id===roleId),m=s.chats[roleId]?.find(x=>x.id===id);if(!r||!m||m.replyDone!==false||!Number.isFinite(m.replyDueAt)||now<m.replyDueAt)return null;m.replyDone=true;let response;const pool=s.stickers||[];if(pool.length&&Math.random()*100<(s.settings.stickerChance??20)){const item=pick(pool);response=message(s,roleId,'[表情] '+item.name,'dream',{type:'sticker',image:item.image,stickerName:item.name});}else response=message(s,roleId,reply(s,lexicon));return {title:r.name,body:response.text,messageId:response.id,page:'chat',role:roleId};}
function settleReplies(s,now=Date.now(),lexicon){const events=[];for(const r of s.roles)for(const m of [...(s.chats[r.id]||[])]){const event=resolveReply(s,r.id,m.id,now,lexicon);if(event)events.push(event);}return events;}

function stitchCount(s){const min=s.settings.stitchMin??1,max=s.settings.stitchMax??4;return min+Math.floor(Math.random()*(max-min+1));}

function receiveState(previous,incoming,preferred=previous?.selected){if(incoming.roles.some(r=>r.id===preferred))incoming.selected=preferred;return incoming;}
function notificationLink(site,event){const url=new URL(site.replace(/\/$/,'')+'/');url.searchParams.set('notice','1');url.searchParams.set('page',event.page||'chat');if(event.role)url.searchParams.set('role',event.role);if(event.messageId)url.searchParams.set('message',event.messageId);return url.href;}

