const json=(data,status=200,origin='')=>new Response(JSON.stringify(data),{status,headers:{'Content-Type':'application/json; charset=utf-8','Cache-Control':'no-store',...(origin?{'Access-Control-Allow-Origin':origin,'Vary':'Origin'}:{})}});
function allowed(request,env){const o=request.headers.get('Origin');return o&&o===env.ALLOWED_ORIGIN?o:'';}
async function auth(request,env){if(!env.BACKEND_TOKEN||env.BACKEND_TOKEN.length<24)return false;const a=new TextEncoder().encode(request.headers.get('Authorization')||''),b=new TextEncoder().encode('Bearer '+env.BACKEND_TOKEN);const hash=async x=>new Uint8Array(await crypto.subtle.digest('SHA-256',x));const x=await hash(a),y=await hash(b);let diff=0;for(let i=0;i<x.length;i++)diff|=x[i]^y[i];return diff===0;}
async function read(env){return env.DB.prepare('SELECT data, revision FROM app_state WHERE id = 1').first();}
async function change(env,fn){for(let retry=0;retry<6;retry++){const row=await read(env),s=row?JSON.parse(row.data):initial();const result=fn(s);const encoded=JSON.stringify(s);if(encoded.length>25*1024*1024)throw Error('数据超过 25MB，请导出并整理图片');const q=row?await env.DB.prepare('UPDATE app_state SET data = ?, revision = revision + 1 WHERE id = 1 AND revision = ?').bind(encoded,row.revision).run():await env.DB.prepare('INSERT OR IGNORE INTO app_state (id,data,revision) VALUES (1,?,1)').bind(encoded).run();if(q.meta.changes===1)return {state:s,result};}throw Error('数据正在更新，请重试');}
async function push(env,event){if(!env.BARK_KEY)throw Error('尚未配置 BARK_KEY');const base=env.BARK_SERVER||'https://api.day.app';const u=new URL(base);if(u.protocol!=='https:')throw Error('Bark 地址必须为 HTTPS');const target=env.SITE_URL?notificationLink(env.SITE_URL,event):undefined;const response=await fetch(base.replace(/\/$/,'')+'/push',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({device_key:env.BARK_KEY,title:event.title,body:event.body,group:'LongLove',sound:'minuet',...(target?{url:target}:{})}),signal:AbortSignal.timeout(12000)});const body=await response.json();if(!response.ok||body.code!==200)throw Error('Bark 拒绝推送，请检查设备密钥');}
async function deliver(env,now){
 const row=await read(env);if(!row||JSON.parse(row.data).settings.backgroundPaused)return;
 await env.DB.prepare('UPDATE outbox SET sent = 2 WHERE sent = 0 AND created_at < ?').bind(now-15*60000).run();
 const recent=await env.DB.prepare('SELECT id FROM outbox WHERE sent = 1 AND created_at > ? LIMIT 1').bind(now-10*60000).first();if(recent)return;
 const pending=await env.DB.prepare('SELECT id,payload FROM outbox WHERE sent = 0 AND attempts < 5 ORDER BY id DESC LIMIT 1').first();if(!pending)return;
 // Keep only the newest pending notification; never replay a burst of backlog.
 await env.DB.prepare('UPDATE outbox SET sent = 2 WHERE sent = 0 AND id < ?').bind(pending.id).run();
 await env.DB.prepare('CREATE TABLE IF NOT EXISTS push_guard (id INTEGER PRIMARY KEY, next_at INTEGER NOT NULL)').run();
 await env.DB.prepare('INSERT OR IGNORE INTO push_guard (id,next_at) VALUES (1,0)').run();
 const gate=await env.DB.prepare('UPDATE push_guard SET next_at = ? WHERE id = 1 AND next_at <= ?').bind(now+10*60000,now).run();if(!gate.meta.changes)return;
 const claim=await env.DB.prepare('UPDATE outbox SET sent = 2 WHERE id = ? AND sent = 0').bind(pending.id).run();if(!claim.meta.changes)return;
 const current=await read(env);if(JSON.parse(current.data).settings.backgroundPaused)return;
 try{await push(env,JSON.parse(pending.payload));await env.DB.prepare('UPDATE outbox SET sent = 1, created_at = ? WHERE id = ?').bind(now,pending.id).run();}catch{await env.DB.prepare('UPDATE outbox SET sent = 0, attempts = attempts + 1 WHERE id = ?').bind(pending.id).run();}
}
async function scheduledTick(env,now=Date.now()){
 if(!env.BARK_KEY)return;
 for(let attempt=0;attempt<5;attempt++){
 const row=await read(env);if(!row)return;const state=JSON.parse(row.data);if(state.settings.backgroundPaused)return;
 const events=tick(state,now,dictionary),encoded=JSON.stringify(state);
 if(encoded===row.data)break;
 const event=events.length===1?events[0]:events.length?{title:'LongLove',body:'有 '+events.length+' 条新互动，打开查看',page:'chat'}:null;
 const queries=[env.DB.prepare('UPDATE app_state SET data = ?, revision = revision + 1 WHERE id = 1 AND revision = ?').bind(encoded,row.revision)];
 if(event)queries.push(env.DB.prepare('INSERT INTO outbox(payload, created_at) SELECT ?, ? WHERE changes() = 1').bind(JSON.stringify(event),now));
 const results=await env.DB.batch(queries);if(results[0].meta.changes===1)break;
 }await deliver(env,now);
}

export default {
async fetch(request,env){const origin=allowed(request,env),given=request.headers.get('Origin');if(given&&!origin)return json({error:'请在 Worker 设置 ALLOWED_ORIGIN 为你的网站源地址'},403);if(request.method==='OPTIONS')return new Response(null,{status:204,headers:{'Access-Control-Allow-Origin':origin,'Access-Control-Allow-Methods':'GET, POST, OPTIONS','Access-Control-Allow-Headers':'Authorization, Content-Type','Access-Control-Max-Age':'86400'}});if(!await auth(request,env))return json({error:'访问令牌无效，或 BACKEND_TOKEN 未配置（至少 24 个字符）'},401,origin);try{const path=new URL(request.url).pathname;if(path==='/state'&&request.method==='GET'){const row=await read(env);return json({state:row?JSON.parse(row.data):null,revision:row?.revision||0,backgroundConfigured:!!env.BARK_KEY},200,origin);}if(path==='/push-test'&&request.method==='POST'){await push(env,{title:'LongLove',body:'收到这条消息，就离彼此更近一点。'});return json({ok:true},200,origin);}if(path==='/action'&&request.method==='POST'){const text=await request.text();if(text.length>30*1024*1024)return json({error:'请求过大'},413,origin);const {type,p}=JSON.parse(text);const result=await change(env,s=>action(s,type,p,dictionary));if(type==='pauseBackground'||type==='resumeBackground')await env.DB.prepare('UPDATE outbox SET sent = 2 WHERE sent = 0').run();return json({state:result.state},200,origin);}return json({error:'未找到接口'},404,origin);}catch(e){return json({error:e.message||'请求失败'},400,origin);}},
async scheduled(controller,env,ctx){ctx.waitUntil(scheduledTick(env,controller.scheduledTime));}
};
export {scheduledTick,change};
